import{_ as r,o as i,c as a,a3 as l,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/unterricht-kataloge/kataloge-zertifikate.png",o="/bilder/unterricht-kataloge/kataloge-zertifikate-schueler-setzen.png",b=JSON.parse('{"title":"Zertifikate am Berufskolleg verwalten und zuordnen","description":"","frontmatter":{"title":"Zertifikate am Berufskolleg verwalten und zuordnen","source_pageid":1313,"source_revision":5028},"headers":[],"relativePath":"schild3/unterricht-kataloge/zertifikate-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/zertifikate-schulbezogene-kataloge.md"}'),d={name:"schild3/unterricht-kataloge/zertifikate-schulbezogene-kataloge.md"};function c(g,t,u,k,h,f){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="zertifikate-am-berufskolleg-verwalten-und-zuordnen" tabindex="-1">Zertifikate am Berufskolleg verwalten und zuordnen <a class="header-anchor" href="#zertifikate-am-berufskolleg-verwalten-und-zuordnen" aria-label="Permalink to &quot;Zertifikate am Berufskolleg verwalten und zuordnen&quot;">​</a></h1><p>Bereiten Sie Zertifikate im Katalog vor und ordnen Sie diese den Schülerinnen und Schülern zu. Der Artikel unterscheidet gespeicherte Angaben, Reportausgabe und externe Druckvorlagen.</p><p><a href="/bilder/unterricht-kataloge/kataloge-zertifikate.png"><img src="'+s+'" alt="Über Kataloge ➜ Zertifikate werden die an der Schule verwalteten Zertifikate festgelegt." loading="lazy"></a></p><p><em>Über Kataloge ➜ Zertifikate werden die an der Schule verwalteten Zertifikate festgelegt.</em></p><p>Am Berufskolleg werden Nachweise über berufliche Qualifikationen, die nicht im Abschlusszeugnis bescheinigt werden und über Zusatzqualifikationen als Zertifikate erteilt.</p><p>Auf Antrag wird auch ein Zertifikat über nicht weitergeführte Ausbildungsabschnitte ausgestellt.</p><p>Ebenso werden Kenntnisse in einer zweiten Fremdsprache entsprechend der aktuell geltenden Vorgaben zertifiziert.</p><p>Erfassen Sie zu vergebenden Zertifikate über <em>Kataloge ➜ Zertifikate</em>.</p><p>Einträge lassen sich anlegen, löschen und bearbeiten.</p><p><a href="/bilder/unterricht-kataloge/kataloge-zertifikate-schueler-setzen.png"><img src="'+o+'" alt="Die Kataloge werden dann über Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben ➜ Zeugnis/Abschluss ➜ Zertifikate gesetzt." loading="lazy"></a></p><p><em>Die Kataloge werden dann über Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben ➜ Zeugnis/Abschluss ➜ <strong>Zertifikate</strong> gesetzt.</em></p><p>Über <em>Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben ➜ Zeugnis/Abschluss</em> ➜ <strong>Zertifikate</strong> öffnet sich ein Fenster mit den eingestellten Zertifikaten, die sich hier über Auswahlboxen dem Schüler zuordnen lassen.</p><p>Bestätigen Sie mit <code>OK</code></p><p>Die für den Schüler vergebenen Zertifikate können über dieses Feld auch angesehen werden.</p><p>In Reports können die Zertifikate über die Datenquelle <em>SchuelerZertifikate</em> ausgegeben werden.</p>',15),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Der eigentliche Druck der Zertifikate findet in der Regel nicht über SchILD-NRW statt, sondern über die extern von der jeweiligen Zertifikatstelle bereitgestellten Vorlagen, die dann in für Textverarbeitung üblichen Formaten vorliegen.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Zertifikate_(Schulbezogene_Kataloge)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5028.")],-1)])])}const m=r(d,[["render",c]]);export{b as __pageData,m as default};
